package br.com.admeclesial.application.relatorio;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.infrastructure.persistence.relatorio.RelatorioMovimentacaoRepository; import org.springframework.data.domain.PageRequest; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal;
@Service public class RelatorioMovimentacaoApplicationService { private final RelatorioMovimentacaoRepository repo; private final SegurancaOrganizacaoService seguranca; public RelatorioMovimentacaoApplicationService(RelatorioMovimentacaoRepository r,SegurancaOrganizacaoService s){repo=r;seguranca=s;}
 @Transactional(readOnly=true) public RelatorioPagina<RelatorioMovimentacaoItem> pesquisar(RelatorioMovimentacaoFiltro f){validar(f);var p=repo.pesquisar(f.organizacaoUuid(),f.dataInicio(),f.dataFim(),f.contaUuid(),tipo(f),f.categoriaUuid(),f.centroCustoUuid(),PageRequest.of(pagina(f),tamanho(f)));var itens=p.getContent().stream().map(x->new RelatorioMovimentacaoItem(x.getUuid(),x.getData(),x.getTipo(),x.getConta(),x.getCategoria(),x.getCentroCusto(),x.getDescricao(),x.getValor(),x.getStatus())).toList();return new RelatorioPagina<>(itens,pagina(f),tamanho(f),p.getTotalElements(),p.getTotalPages(),"data","desc");}
 @Transactional(readOnly=true) public RelatorioMovimentacaoResumo resumo(RelatorioMovimentacaoFiltro f){validar(f);var r=repo.resumo(f.organizacaoUuid(),f.dataInicio(),f.dataFim(),f.contaUuid(),tipo(f),f.categoriaUuid(),f.centroCustoUuid());var e=nvl(r.getTotalEntradas());var s=nvl(r.getTotalSaidas());return new RelatorioMovimentacaoResumo(e,s,e.subtract(s));}
 private void validar(RelatorioMovimentacaoFiltro f){if(f.organizacaoUuid()==null)throw new IllegalArgumentException("Organização é obrigatória");if(f.dataInicio()!=null&&f.dataFim()!=null&&f.dataFim().isBefore(f.dataInicio()))throw new IllegalArgumentException("Data final não pode ser anterior à data inicial");seguranca.validarAcesso(f.organizacaoUuid());} private String tipo(RelatorioMovimentacaoFiltro f){return f.tipo()==null?null:f.tipo().name();} private int pagina(RelatorioMovimentacaoFiltro f){return Math.max(0,f.pagina());} private int tamanho(RelatorioMovimentacaoFiltro f){return Math.max(10,Math.min(100,f.tamanho()));} private BigDecimal nvl(BigDecimal v){return v==null?BigDecimal.ZERO:v;}
}
